// ---------------------------------------------------------------- pictograms
function drawArt(kind: number, x: number, y: number, s: number, c: number[]): void {
  const WHT = [255, 255, 255];
  if (kind === 0) {
    // bar chart + rising tariff arrow (trade)
    fillRect(x + 8, y + 58, 16, 34, c);
    fillRect(x + 32, y + 42, 16, 50, c);
    fillRect(x + 56, y + 26, 16, 66, c);
    drawLine(x + 6, y + 18, x + 82, y + 8, WHT, 4);
    fillTriangle(x + 82, y + 8, x + 66, y + 6, x + 80, y + 22, WHT);
    drawText("%", x + 78, y + 52, 2, WHT);
  } else if (kind === 1) {
    // fuel tanker truck + flame (Cairo)
    roundRect(x + 6, y + 48, 52, 26, 8, c);
    fillRect(x + 58, y + 54, 22, 20, c);
    fillRect(x + 62, y + 58, 12, 10, [11, 27, 46]);
    fillCircle(x + 20, y + 78, 9, [17, 24, 39]);
    fillCircle(x + 66, y + 78, 9, [17, 24, 39]);
    fillCircle(x + 20, y + 78, 4, WHT);
    fillCircle(x + 66, y + 78, 4, WHT);
    fillTriangle(x + 22, y + 44, x + 34, y + 12, x + 46, y + 44, [251, 191, 36]);
    fillTriangle(x + 28, y + 44, x + 34, y + 26, x + 40, y + 44, [239, 68, 68]);
  } else if (kind === 2) {
    // courthouse: pediment + columns (trial)
    fillTriangle(x + 8, y + 14, x + 46, y + 40, x + 84, y + 14, c);
    fillRect(x + 14, y + 44, 8, 40, c);
    fillRect(x + 42, y + 44, 8, 40, c);
    fillRect(x + 70, y + 44, 8, 40, c);
    fillRect(x + 8, y + 86, 76, 6, c);
  } else if (kind === 3) {
    // jet + blast star (air base strike)
    fillTriangle(x + 10, y + 46, x + 78, y + 40, x + 10, y + 58, c);
    fillTriangle(x + 34, y + 40, x + 46, y + 22, x + 52, y + 42, c);
    fillTriangle(x + 34, y + 58, x + 46, y + 76, x + 52, y + 56, c);
    fillTriangle(x + 12, y + 46, x + 20, y + 38, x + 20, y + 54, c);
    fillCircle(x + 80, y + 26, 5, [251, 191, 36]);
    drawLine(x + 80, y + 12, x + 80, y + 40, [251, 191, 36], 3);
    drawLine(x + 66, y + 26, x + 94, y + 26, [251, 191, 36], 3);
  } else if (kind === 4) {
    // mushroom cloud (nuclear deployment)
    fillCircle(x + 46, y + 30, 20, c);
    fillCircle(x + 28, y + 38, 13, c);
    fillCircle(x + 64, y + 38, 13, c);
    fillRect(x + 38, y + 44, 16, 34, c);
    fillRect(x + 28, y + 78, 36, 8, c);
    fillCircle(x + 46, y + 30, 8, [251, 191, 36]);
  } else if (kind === 5) {
    // falling market chart (stocks slide)
    drawLine(x + 8, y + 20, x + 26, y + 34, WHT, 4);
    drawLine(x + 26, y + 34, x + 44, y + 30, WHT, 4);
    drawLine(x + 44, y + 30, x + 62, y + 58, WHT, 4);
    drawLine(x + 62, y + 58, x + 82, y + 74, WHT, 4);
    fillTriangle(x + 82, y + 74, x + 62, y + 72, x + 80, y + 88, [239, 68, 68]);
    drawLine(x + 8, y + 86, x + 88, y + 86, WHT, 3);
  }
}

// ---------------------------------------------------------------- render
const NAVY = [11, 27, 46];
const NAVY2 = [16, 38, 64];
const PAPER = [244, 246, 248];
const INK = [15, 23, 42];
const MUTED = [71, 85, 105];
const RED = [220, 38, 38];
const WHITE = [255, 255, 255];

function render(): void {
  fillRect(0, 0, W, H, PAPER);
  // header
  fillRect(0, 0, W, 148, NAVY);
  fillRect(0, 142, W, 6, RED);
  const kicker = "WORLD NEWS IN ONE IMAGE";
  drawText(kicker, (W - textWidth(kicker, 2)) / 2, 22, 2, [147, 197, 253]);
  const dateLine = "THURSDAY 26 NOVEMBER 2026";
  drawText(dateLine, (W - textWidth(dateLine, 4)) / 2, 52, 4, WHITE);
  const sub = "SIX STORIES THAT DEFINED THE DAY";
  drawText(sub, (W - textWidth(sub, 2)) / 2, 108, 2, [203, 213, 225]);

  // story rows
  const top = 160, gap = 8;
  const rowH = Math.floor((H - 40 - top - (STORIES.length - 1) * gap) / STORIES.length);
  STORIES.forEach((st, i) => {
    const y = top + i * (rowH + gap);
    fillRect(16, y, W - 32, rowH, i % 2 === 0 ? WHITE : NAVY2);
    const fg = i % 2 === 0 ? INK : WHITE;
    const sub2 = i % 2 === 0 ? MUTED : [203, 213, 225];
    // pictogram panel
    roundRect(28, y + 12, 108, rowH - 24, 12, st.tagColor);
    drawArt(st.art, 28 + 8, y + 12 + 8, 1, WHITE);
    // tag + number
    drawText(String(i + 1) + ".  " + st.tag, 156, y + 14, 1, st.tagColor);
    drawText(st.headline, 156, y + 36, 2, fg);
    const lines = wrapText(st.caption, 1, W - 156 - 24);
    lines.slice(0, 2).forEach((ln, li) => drawText(ln, 156, y + 68 + li * 14, 1, sub2));
  });

  // footer
  const foot = "SOURCES: REUTERS - KCNA - IBC GLOBAL TIMES  |  ALL STORIES REPORTED 26 NOV 2026";
  drawText(foot, (W - textWidth(foot, 1)) / 2, H - 26, 1, MUTED);
}

function selfCheck(outDir: string): void {
  // Re-read the written PNG and assert its header, dimensions and size.
  const p = join(outDir, "entry.png");
  const b = readFileSync(p);
  const sig = [137, 80, 78, 71, 13, 10, 26, 10];
  for (let i = 0; i < 8; i++) if (b[i] !== sig[i]) throw new Error("bad PNG signature");
  if (b.toString("ascii", 12, 16) !== "IHDR") throw new Error("missing IHDR");
  const w = b.readUInt32BE(16), h = b.readUInt32BE(20);
  if (w !== W || h !== H) throw new Error(`bad dimensions ${w}x${h}, expected ${W}x${H}`);
  if (b.length >= 1024 * 1024) throw new Error(`PNG too large: ${b.length} bytes`);
  if (b.toString("ascii", b.length - 8, b.length - 4) !== "IEND") throw new Error("missing IEND");
  console.log(`self-check OK: ${w}x${h}, ${b.length} bytes, signature+IHDR+IEND valid`);
}

function main(): void {
  render();
  const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
  mkdirSync(outDir, { recursive: true });
  const buf = encodePNG();
  writeFileSync(join(outDir, "entry.png"), buf);
  console.log(`wrote entry.png ${buf.length} bytes ${W}x${H}`);
  selfCheck(outDir);
}

main();
